write('shared/npm.mjs', '''
import {existsSync} from 'node:fs';import {dirname,join} from 'node:path';import {fileURLToPath} from 'node:url';import {spawnNode} from './lab.mjs';
export function npm(args,options={}){const candidates=[process.env.npm_execpath,join(dirname(process.execPath),'node_modules/npm/bin/npm-cli.js'),'/usr/share/nodejs/npm/bin/npm-cli.js','/usr/local/lib/node_modules/npm/bin/npm-cli.js'].filter(Boolean);const cli=candidates.find(existsSync);if(!cli)throw Error('Run with npm run lesson -- NUMBER.');return spawnNode([cli,...args],{...options,env:{...process.env,NPM_CONFIG_CACHE:fileURLToPath(new URL('../.npm-cache/',import.meta.url)),...options.env}});}
''')
write('shared/env.mjs', '''
import {existsSync} from 'node:fs';import {fileURLToPath} from 'node:url';
const envFile=fileURLToPath(new URL('../.env',import.meta.url));if(existsSync(envFile))process.loadEnvFile(envFile);
export function localURL(value,fallback){const url=new URL(value??fallback);if(!['127.0.0.1','localhost'].includes(url.hostname)&&process.env.COURSE_ALLOW_REMOTE_LAB!=='1')throw Error('Use a local disposable course service, not a production database.');return url;}
''')
write('tools/setup.mjs', '''
import {randomBytes} from 'node:crypto';import {writeFile} from 'node:fs/promises';
const password=randomBytes(24).toString('hex');const text=`DB_PASSWORD=${password}\\nDATABASE_URL=postgres://course:${password}@127.0.0.1:55432/course_lab\\nREDIS_URL=redis://127.0.0.1:56379\\nMONGODB_URL=mongodb://127.0.0.1:57017\\n`;
try{await writeFile(new URL('../.env',import.meta.url),text,{flag:'wx',mode:0o600});console.log('Created local .env; credentials were not printed.');}catch(e){if(e.code!=='EEXIST')throw e;console.log('Existing .env preserved.');}
''')
write('compose.yaml', '''
name: node-course-lab
services:
  db:
    image: postgres:17
    environment:
      POSTGRES_USER: course
      POSTGRES_DB: course_lab
      POSTGRES_PASSWORD: ${DB_PASSWORD:?Run node tools/setup.mjs}
    ports: ["127.0.0.1:55432:5432"]
    volumes: ["pgdata:/var/lib/postgresql/data"]
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U course -d course_lab"]
      interval: 2s
      timeout: 3s
      retries: 30
  redis:
    image: redis:7
    command: ["redis-server", "--appendonly", "yes"]
    ports: ["127.0.0.1:56379:6379"]
    volumes: ["redisdata:/data"]
    healthcheck:
      test: ["CMD", "redis-cli", "ping"]
      interval: 2s
      timeout: 3s
      retries: 30
  mongo:
    image: mongo:8
    ports: ["127.0.0.1:57017:27017"]
    volumes: ["mongodata:/data/db"]
volumes:
  pgdata:
  redisdata:
  mongodata:
''')
write('shared/postgres.mjs', '''
import {Pool} from 'pg';import {randomUUID} from 'node:crypto';import {localURL} from './env.mjs';
export async function pgLab(){if(!process.env.DATABASE_URL)throw Error('Run node tools/setup.mjs and docker compose up -d db first.');const url=localURL(process.env.DATABASE_URL);const schema='lab_'+randomUUID().replaceAll('-','');const admin=new Pool({connectionString:url.href,max:1,connectionTimeoutMillis:2000,statement_timeout:5000});let pool;try{await admin.query('CREATE SCHEMA '+schema);pool=new Pool({connectionString:url.href,max:5,connectionTimeoutMillis:2000,statement_timeout:5000,options:'-c search_path='+schema});await pool.query(`CREATE TABLE tasks(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,owner_id TEXT NOT NULL DEFAULT 'user-a',version INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE TABLE accounts(id INTEGER PRIMARY KEY,balance INTEGER NOT NULL CHECK(balance>=0));INSERT INTO accounts VALUES(1,100),(2,50);CREATE TABLE reports(id TEXT PRIMARY KEY,owner_id TEXT,status TEXT NOT NULL,result JSONB);CREATE TABLE outbox(id TEXT PRIMARY KEY,topic TEXT NOT NULL,payload JSONB NOT NULL,published BOOLEAN NOT NULL DEFAULT false);CREATE TABLE processed_events(id TEXT PRIMARY KEY);CREATE TABLE room_events(id BIGSERIAL PRIMARY KEY,room_id TEXT NOT NULL,payload JSONB NOT NULL);CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL);`);return {pool,schema,async [Symbol.asyncDispose](){await pool.end();try{await admin.query('DROP SCHEMA '+schema+' CASCADE');}finally{await admin.end();}}};}catch(e){await pool?.end();await admin.end();throw e;}}
export async function transaction(pool,work){const client=await pool.connect();try{await client.query('BEGIN');const result=await work(client);await client.query('COMMIT');return result;}catch(e){await client.query('ROLLBACK');throw e;}finally{client.release();}}
''')
write('shared/redis.mjs', '''
import {createClient} from 'redis';import {randomUUID} from 'node:crypto';import {localURL} from './env.mjs';
export function redisConnection(){const url=localURL(process.env.REDIS_URL,'redis://127.0.0.1:56379');return{host:url.hostname,port:Number(url.port||6379),password:url.password?decodeURIComponent(url.password):undefined,maxRetriesPerRequest:null};}
export async function redisLab(){const url=localURL(process.env.REDIS_URL,'redis://127.0.0.1:56379');const client=createClient({url:url.href,socket:{connectTimeout:2000,reconnectStrategy:false}});client.on('error',()=>{});await client.connect();const prefix='course:'+randomUUID()+':';return{client,prefix,async [Symbol.asyncDispose](){if(client.isOpen){const keys=await client.keys(prefix+'*');if(keys.length)await client.del(keys);await client.quit();}}};}
''')
write('shared/jobs.mjs', '''
import {Queue,QueueEvents,Worker} from 'bullmq';import {randomUUID} from 'node:crypto';import {redisConnection} from './redis.mjs';
export async function queueLab(processor){const name='course-'+randomUUID();const connection=redisConnection();const queue=new Queue(name,{connection}),events=new QueueEvents(name,{connection});events.on('error',()=>{});await events.waitUntilReady();const worker=new Worker(name,processor,{connection,concurrency:2});worker.on('error',()=>{});await worker.waitUntilReady();return{queue,events,worker,name,connection,async [Symbol.asyncDispose](){await worker.close();await queue.obliterate({force:true});await events.close();await queue.close();}};}
''')
add(85,'''import {Database} from 'node:sqlite';import {assert,fs,temp,join} from '../../shared/lab.mjs';await using lab=await temp();const file=join(lab.path,'notes.db');for(let pass=1;pass<=2;pass++){const db=new Database(file);try{db.exec('CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY,text TEXT NOT NULL)');using insert=db.prepare('INSERT INTO notes(text) VALUES (?)');insert.run('Learn Node.js');using read=db.prepare('SELECT * FROM notes ORDER BY id');const rows=read.all();console.log(rows);assert.equal(rows.length,pass);}finally{db.close();}}''','Reopening the real SQLite file preserves the first record; each execution inserts another record. Database operations remain synchronous.')
add(86,'''import {pgLab} from '../../shared/postgres.mjs';import assert from 'node:assert/strict';await using lab=await pgLab();const title="x'; DROP TABLE tasks; --";await lab.pool.query('INSERT INTO tasks(title) VALUES($1)',[title]);const rows=(await lab.pool.query('SELECT id,title FROM tasks WHERE title=$1',[title])).rows;console.log(rows);assert.equal(rows[0].title,title);assert.equal((await lab.pool.query('SELECT count(*) FROM tasks')).rows[0].count,'1');''','The parameterized attack-shaped title is stored as ordinary data and the table remains intact.',mode='postgres',deps=['pg'])
add(87,'''import {pgLab,transaction} from '../../shared/postgres.mjs';import assert from 'node:assert/strict';await using lab=await pgLab();async function transfer(fail){return transaction(lab.pool,async client=>{await client.query('SELECT id FROM accounts WHERE id IN(1,2) ORDER BY id FOR UPDATE');await client.query('UPDATE accounts SET balance=balance-10 WHERE id=1');if(fail)throw Error('injected failure');await client.query('UPDATE accounts SET balance=balance+10 WHERE id=2');});}await assert.rejects(transfer(true));let rows=(await lab.pool.query('SELECT * FROM accounts ORDER BY id')).rows;assert.deepEqual(rows.map(x=>x.balance),[100,50]);await transfer(false);rows=(await lab.pool.query('SELECT * FROM accounts ORDER BY id')).rows;console.log(rows);assert.deepEqual(rows.map(x=>x.balance),[90,60]);''','Failure between updates rolls back both balances; success preserves the total with deterministic lock ordering.',mode='postgres',deps=['pg'])
add(88,'''import {pgLab,transaction} from '../../shared/postgres.mjs';import assert from 'node:assert/strict';await using lab=await pgLab();await lab.pool.query('CREATE TABLE migration_versions(version INTEGER PRIMARY KEY)');await transaction(lab.pool,async client=>{await client.query('ALTER TABLE tasks ADD COLUMN priority INTEGER NOT NULL DEFAULT 0');await client.query('INSERT INTO migration_versions VALUES(1)');});await lab.pool.query("INSERT INTO tasks(title) VALUES('persisted fixture')");assert.equal((await lab.pool.query('SELECT priority FROM tasks')).rows[0].priority,0);console.log('additive migration applied; existing/default data verified');''','A migration is applied transactionally and its default preserves compatibility. A complete node-pg-migrate file is also supplied.','For CLI practice set DATABASE_URL to a disposable DB and run npm exec node-pg-migrate -- up --migrations-dir lessons/prompt-088/migrations from the workspace. Never roll back a production table for a classroom exercise.',files={'migrations/001_create_notes.cjs':"exports.up=pgm=>{pgm.createTable('migration_notes',{id:'id',title:{type:'text',notNull:true}});};exports.down=pgm=>{pgm.dropTable('migration_notes');};"},mode='postgres',deps=['pg','node-pg-migrate'])
add(89,'''import {pgLab} from '../../shared/postgres.mjs';import assert from 'node:assert/strict';await using lab=await pgLab();const {rows:[task]}=await lab.pool.query("INSERT INTO tasks(title) VALUES('original') RETURNING *");const results=await Promise.all(['edit A','edit B'].map(title=>lab.pool.query('UPDATE tasks SET title=$1,version=version+1 WHERE id=$2 AND version=$3 RETURNING *',[title,task.id,task.version])));console.log(results.map(x=>({status:x.rowCount?200:409,rows:x.rows})));assert.deepEqual(results.map(x=>x.rowCount).sort(),[0,1]);''','Two concurrent updates using the same expected version produce one success and one conflict.',mode='postgres',deps=['pg'])
add(90,'''import {MongoClient} from 'mongodb';import {randomUUID} from 'node:crypto';import {localURL} from '../../shared/env.mjs';import assert from 'node:assert/strict';const client=new MongoClient(localURL(process.env.MONGODB_URL,'mongodb://127.0.0.1:57017').href,{serverSelectionTimeoutMS:2000});const name='course_'+randomUUID().replaceAll('-','');try{await client.connect();const db=client.db(name);await db.createCollection('products',{validator:{$jsonSchema:{bsonType:'object',required:['sku','price'],properties:{sku:{bsonType:'string'},price:{bsonType:'number',minimum:0}}}}});const products=db.collection('products');await products.createIndex({sku:1},{unique:true});await products.updateOne({sku:'demo-1'},{$setOnInsert:{price:10}},{upsert:true});console.log(await products.findOne({sku:'demo-1'}));await assert.rejects(products.insertOne({sku:'demo-1',price:20}),{code:11000});console.log((await products.find({sku:'demo-1'}).explain('executionStats')).executionStats);await db.dropDatabase();}finally{await client.close();}''','A unique SKU index supports an idempotent upsert; a duplicate insert is rejected and the real query plan is displayed.',mode='mongodb',deps=['mongodb'])
add(91,'''import {pgLab} from '../../shared/postgres.mjs';import {redisLab} from '../../shared/redis.mjs';import assert from 'node:assert/strict';await using db=await pgLab();await using redis=await redisLab();const {rows:[task]}=await db.pool.query("INSERT INTO tasks(title) VALUES('first') RETURNING *");const key=redis.prefix+'task:'+task.id;let loads=0;async function load(){try{const hit=await redis.client.get(key);if(hit!==null)return JSON.parse(hit);}catch{}loads++;const value=(await db.pool.query('SELECT * FROM tasks WHERE id=$1',[task.id])).rows[0];try{await redis.client.set(key,JSON.stringify(value),{EX:30});}catch{}return value;}await load();await load();assert.equal(loads,1);await db.pool.query('UPDATE tasks SET title=$1 WHERE id=$2',['changed',task.id]);await redis.client.del(key);assert.equal((await load()).title,'changed');await redis.client.quit();assert.equal((await load()).title,'changed');console.log({databaseLoads:loads,cacheFailureFallback:true});''','Miss loads DB, hit avoids it, commit-plus-invalidation refreshes it, and a closed cache falls back to PostgreSQL.',mode='postgres+redis',deps=['pg','redis'])
add(92,'''import {redisLab} from '../../shared/redis.mjs';import assert from 'node:assert/strict';await using lab=await redisLab();const subscriber=lab.client.duplicate();subscriber.on('error',()=>{});await subscriber.connect();const channel=lab.prefix+'updates',stream=lab.prefix+'events';try{const received=new Promise(resolve=>subscriber.subscribe(channel,resolve));await new Promise(r=>setTimeout(r,30));await lab.client.publish(channel,'hello');assert.equal(await received,'hello');await subscriber.unsubscribe(channel);await lab.client.publish(channel,'offline message');const id=await lab.client.xAdd(stream,'*',{type:'hello'});await lab.client.xGroupCreate(stream,'workers','0',{MKSTREAM:true});const rows=await lab.client.xReadGroup('workers','c1',{key:stream,id:'>'},{COUNT:1});console.log(rows);assert.equal(rows[0].messages[0].id,id);assert.equal(await lab.client.xAck(stream,'workers',id),1);console.log('Pub/Sub live delivery vs retained stream read+ACK');}finally{await subscriber.quit();}''','Pub/Sub delivers only to a live subscriber; the retained stream is read through a consumer group and acknowledged.',mode='redis',deps=['redis'])
add(93,'''import {queueLab} from '../../shared/jobs.mjs';import assert from 'node:assert/strict';let attempts=0;await using lab=await queueLab(async job=>{attempts++;if(job.attemptsMade<2)throw Error('transient fixture');return{reportId:job.data.reportId};});const job=await lab.queue.add('generate',{reportId:'r1'},{jobId:'report-r1',attempts:3,backoff:{type:'exponential',delay:10}});const value=await job.waitUntilFinished(lab.events,10000);console.log({value,attempts});assert.equal(attempts,3);''','The worker fails twice and succeeds within a three-attempt retry budget; job resources are closed.',mode='redis',deps=['bullmq'])
add(94,'''import {queueLab} from '../../shared/jobs.mjs';import {delay,assert} from '../../shared/lab.mjs';let active=0,max=0;await using lab=await queueLab(async()=>{active++;max=Math.max(max,active);try{await delay(20);return'done';}finally{active--;}});await lab.queue.upsertJobScheduler('nightly-report',{pattern:'0 0 9 * * *',tz:'Europe/Madrid'},{name:'generate',data:{reportId:'daily'}});await lab.queue.setGlobalConcurrency(1);console.log(await lab.queue.getJobSchedulers());const jobs=await Promise.all([1,2,3].map(i=>lab.queue.add('immediate',{i})));await Promise.all(jobs.map(job=>job.waitUntilFinished(lab.events,10000)));assert.equal(max,1);console.log('measured maximum active jobs:',max);await lab.queue.removeJobScheduler('nightly-report');''','The real scheduler records an explicit timezone; immediate jobs verify the global concurrency bound. Tomorrow’s scheduled execution is not claimed.',mode='redis',deps=['bullmq'])
write('shared/outbox.mjs', '''
import {transaction} from './postgres.mjs';
export async function createReport(pool,id,owner='user-a'){return transaction(pool,async client=>{const inserted=await client.query('INSERT INTO reports(id,owner_id,status) VALUES($1,$2,$3) ON CONFLICT(id) DO NOTHING RETURNING id',[id,owner,'pending']);if(inserted.rowCount)await client.query('INSERT INTO outbox(id,topic,payload) VALUES($1,$2,$3)',[id,'report.requested',{reportId:id}]);});}
export async function publishResult(pool,eventId,reportId){return transaction(pool,async client=>{const inserted=await client.query('INSERT INTO processed_events(id) VALUES($1) ON CONFLICT DO NOTHING RETURNING id',[eventId]);if(inserted.rowCount)await client.query('UPDATE reports SET status=$1,result=$2 WHERE id=$3',['complete',{total:42},reportId]);return inserted.rowCount;});}
''')
add(95,'''import {pgLab} from '../../shared/postgres.mjs';import {createReport,publishResult} from '../../shared/outbox.mjs';import {queueLab} from '../../shared/jobs.mjs';import assert from 'node:assert/strict';await using db=await pgLab();await createReport(db.pool,'r1');await using queue=await queueLab(job=>publishResult(db.pool,job.data.eventId,job.data.reportId));const event=(await db.pool.query('SELECT * FROM outbox WHERE published=false')).rows[0];for(let delivery=0;delivery<2;delivery++){const job=await queue.queue.add('report',{eventId:event.id,...event.payload},{jobId:'delivery-'+delivery});await job.waitUntilFinished(queue.events,10000);}await db.pool.query('UPDATE outbox SET published=true WHERE id=$1',[event.id]);assert.equal((await db.pool.query('SELECT count(*) FROM processed_events')).rows[0].count,'1');console.log((await db.pool.query('SELECT * FROM reports')).rows);''','Two deliveries produce one durable business effect, protected by a PostgreSQL uniqueness constraint and transaction.',mode='postgres+redis',deps=['pg','bullmq'])
